-- Lot 3 — Référentiel scientifique GBIF + notes de site (map_species.site_notes).
-- Idempotent. Seeds : sql/biodiv_structure_seeds/03 et 04.

ALTER TABLE plants
  ADD COLUMN IF NOT EXISTS accepted_scientific_name VARCHAR(255) DEFAULT NULL COMMENT 'Nom accepté (GBIF) si différent du nom d''usage';
ALTER TABLE plants
  ADD COLUMN IF NOT EXISTS gbif_accepted_key INT UNSIGNED DEFAULT NULL COMMENT 'Clé GBIF du nom accepté';
ALTER TABLE plants
  ADD COLUMN IF NOT EXISTS taxon_phylum VARCHAR(96) DEFAULT NULL COMMENT 'Embranchement (latin, GBIF)';
ALTER TABLE plants
  ADD COLUMN IF NOT EXISTS taxon_class VARCHAR(96) DEFAULT NULL COMMENT 'Classe (latin, GBIF)';
ALTER TABLE plants
  ADD COLUMN IF NOT EXISTS taxon_order VARCHAR(96) DEFAULT NULL COMMENT 'Ordre (latin, GBIF)';
ALTER TABLE plants
  ADD COLUMN IF NOT EXISTS taxon_family_latin VARCHAR(96) DEFAULT NULL COMMENT 'Famille (latin, GBIF)';
ALTER TABLE plants
  ADD COLUMN IF NOT EXISTS gbif_checked_at DATE DEFAULT NULL COMMENT 'Dernière vérification GBIF';

ALTER TABLE map_species
  ADD COLUMN IF NOT EXISTS site_notes TEXT DEFAULT NULL COMMENT 'Observations propres à ce site (effectifs, nidification, localisation)';

